INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (507, 1, '앱 전용 계정 만들기 (접속 호스트 제한)', '`shop` 데이터베이스를 쓰는 앱을 위해 계정을 하나 만듭니다. 계정 이름은 **`appuser`**, 접속을 허용할 곳은 **이 서버 안(`localhost`)만**, 비밀번호는 **`AppPass1`** 입니다. MariaDB 계정은 `''이름''@''접속 위치''` 두 부분으로 이루어져, 같은 이름이라도 접속 위치가 다르면 다른 계정입니다. 만든 뒤 그 계정으로 접속해 `SELECT 1` 이 되어야 합니다.', '`CREATE USER ''이름''@''호스트'' IDENTIFIED BY ''비밀번호'';` 를 `mariadb -e` 로 실행합니다. 접속 시험은 `mariadb -u이름 -p비밀번호 -e "SELECT 1"` 입니다.', 'mariadb -e "CREATE USER ''appuser''@''localhost'' IDENTIFIED BY ''AppPass1''"
mariadb -uappuser -pAppPass1 -e ''SELECT 1''

# 호스트 부분을 localhost 로 두면 그 서버 안에서만 접속할 수 있다. ''%'' 는 어디서나 접속 허용이라 꼭 필요할 때만 쓴다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP USER IF EXISTS \\"appuser\\"@\\"localhost\\"; DROP USER IF EXISTS \\"reader\\"@\\"localhost\\"; DROP USER IF EXISTS \\"report\\"@\\"localhost\\"; DROP USER IF EXISTS \\"olduser\\"@\\"localhost\\"; DROP USER IF EXISTS \\"alice\\"@\\"localhost\\"; DROP USER IF EXISTS \\"bob\\"@\\"localhost\\"; DROP USER IF EXISTS \\"backup\\"@\\"localhost\\"; DROP USER IF EXISTS \\"backup\\"@\\"%\\"; DROP ROLE IF EXISTS reader_role; DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; CREATE TABLE shop.items (id INT PRIMARY KEY, name VARCHAR(30), price INT); INSERT INTO shop.items VALUES (1,\\"apple\\",1000),(2,\\"pear\\",2000),(3,\\"grape\\",3000),(4,\\"peach\\",4000),(5,\\"plum\\",5000);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( mariadb -N -e ''SELECT COUNT(*) FROM mysql.user WHERE user=\\"appuser\\" AND host=\\"localhost\\"'' | grep -qx 1 ) && ( mariadb -uappuser -pAppPass1 -N -e \\"SELECT 1\\" | grep -qx 1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "appuser@localhost 계정이 있다", "cmd": ["sh", "-c", "mariadb -N -e ''SELECT COUNT(*) FROM mysql.user WHERE user=\\"appuser\\" AND host=\\"localhost\\"'' | grep -qx 1"]}, {"label": "그 계정으로 접속된다", "cmd": ["sh", "-c", "mariadb -uappuser -pAppPass1 -N -e \\"SELECT 1\\" | grep -qx 1"]}]', '[{"title": "CREATE USER", "url": "https://mariadb.com/kb/en/create-user/"}, {"title": "GRANT", "url": "https://mariadb.com/kb/en/grant/"}, {"title": "Roles", "url": "https://mariadb.com/kb/en/roles_overview/"}]'),
  (507, 2, '필요한 권한만 주기', '`appuser` 가 만들어져 있지만 **아직 아무 데이터도 볼 수 없습니다**. 앱은 `shop` 의 모든 테이블을 **조회·추가·수정·삭제**만 하면 됩니다. 이 네 가지 권한(`SELECT, INSERT, UPDATE, DELETE`)만 `shop.*` 에 주세요. 테이블을 만들거나 지우는 권한까지 주는 `ALL` 은 쓰지 않습니다.', '`GRANT 권한, 권한 ON DB이름.* TO ''계정''@''호스트'';` 형식입니다. `shop.*` 는 shop 의 모든 테이블을 뜻합니다.', 'mariadb -e "GRANT SELECT, INSERT, UPDATE, DELETE ON shop.* TO ''appuser''@''localhost''"
mariadb -e "SHOW GRANTS FOR ''appuser''@''localhost''"

# 필요한 만큼만 주는 것이 최소 권한 원칙. 앱이 침해돼도 피해가 shop 의 데이터 변경까지로 한정된다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP USER IF EXISTS \\"appuser\\"@\\"localhost\\"; DROP USER IF EXISTS \\"reader\\"@\\"localhost\\"; DROP USER IF EXISTS \\"report\\"@\\"localhost\\"; DROP USER IF EXISTS \\"olduser\\"@\\"localhost\\"; DROP USER IF EXISTS \\"alice\\"@\\"localhost\\"; DROP USER IF EXISTS \\"bob\\"@\\"localhost\\"; DROP USER IF EXISTS \\"backup\\"@\\"localhost\\"; DROP USER IF EXISTS \\"backup\\"@\\"%\\"; DROP ROLE IF EXISTS reader_role; DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; CREATE TABLE shop.items (id INT PRIMARY KEY, name VARCHAR(30), price INT); INSERT INTO shop.items VALUES (1,\\"apple\\",1000),(2,\\"pear\\",2000),(3,\\"grape\\",3000),(4,\\"peach\\",4000),(5,\\"plum\\",5000);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf; mariadb -e ''CREATE USER \\"appuser\\"@\\"localhost\\" IDENTIFIED BY \\"AppPass1\\";''"]', '["sh", "-c", "( mariadb -N -e ''SELECT GROUP_CONCAT(privilege_type ORDER BY privilege_type) FROM information_schema.schema_privileges WHERE grantee LIKE \\"%appuser%\\" AND table_schema=\\"shop\\"'' | grep -qx \\"DELETE,INSERT,SELECT,UPDATE\\" ) && ( mariadb -uappuser -pAppPass1 -N -e \\"SELECT COUNT(*) FROM shop.items\\" | grep -qx 5 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "shop 에 네 권한이 있다", "cmd": ["sh", "-c", "mariadb -N -e ''SELECT GROUP_CONCAT(privilege_type ORDER BY privilege_type) FROM information_schema.schema_privileges WHERE grantee LIKE \\"%appuser%\\" AND table_schema=\\"shop\\"'' | grep -qx \\"DELETE,INSERT,SELECT,UPDATE\\""]}, {"label": "앱 계정으로 조회된다", "cmd": ["sh", "-c", "mariadb -uappuser -pAppPass1 -N -e \\"SELECT COUNT(*) FROM shop.items\\" | grep -qx 5"]}]', '[{"title": "CREATE USER", "url": "https://mariadb.com/kb/en/create-user/"}, {"title": "GRANT", "url": "https://mariadb.com/kb/en/grant/"}, {"title": "Roles", "url": "https://mariadb.com/kb/en/roles_overview/"}]'),
  (507, 3, '읽기 전용 계정과 거부 오류', '분석 담당자를 위한 **읽기 전용 계정**을 만듭니다. 이름 **`reader`**, 위치 `localhost`, 비밀번호 **`ReadPass1`**, 권한은 `shop.*` 에 **`SELECT` 만** 줍니다. 그다음 이 계정으로 `shop.items` 에 `INSERT` 를 시도해 **거부되는 오류 메시지를 `/tmp/denied.txt`** 에 저장하세요. (INSERT 는 아무 값이나 괜찮습니다.)', '계정을 만들고 `GRANT SELECT ...` 한 뒤, `mariadb -ureader -pReadPass1 shop -e "INSERT ..." 2> /tmp/denied.txt` 처럼 오류(표준 에러)를 파일로 보냅니다. 오류 번호는 1142 입니다.', 'mariadb -e "CREATE USER ''reader''@''localhost'' IDENTIFIED BY ''ReadPass1''; GRANT SELECT ON shop.* TO ''reader''@''localhost''"
mariadb -ureader -pReadPass1 shop -e "INSERT INTO items VALUES (6,''kiwi'',6000)" 2> /tmp/denied.txt
cat /tmp/denied.txt

# 권한이 없는 동작은 ERROR 1142 ... command denied 로 거부된다. 읽기만 필요한 사람에게는 SELECT 만 준다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP USER IF EXISTS \\"appuser\\"@\\"localhost\\"; DROP USER IF EXISTS \\"reader\\"@\\"localhost\\"; DROP USER IF EXISTS \\"report\\"@\\"localhost\\"; DROP USER IF EXISTS \\"olduser\\"@\\"localhost\\"; DROP USER IF EXISTS \\"alice\\"@\\"localhost\\"; DROP USER IF EXISTS \\"bob\\"@\\"localhost\\"; DROP USER IF EXISTS \\"backup\\"@\\"localhost\\"; DROP USER IF EXISTS \\"backup\\"@\\"%\\"; DROP ROLE IF EXISTS reader_role; DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; CREATE TABLE shop.items (id INT PRIMARY KEY, name VARCHAR(30), price INT); INSERT INTO shop.items VALUES (1,\\"apple\\",1000),(2,\\"pear\\",2000),(3,\\"grape\\",3000),(4,\\"peach\\",4000),(5,\\"plum\\",5000);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf"]', '["sh", "-c", "( mariadb -N -e ''SELECT GROUP_CONCAT(privilege_type) FROM information_schema.schema_privileges WHERE grantee LIKE \\"%reader%\\" AND table_schema=\\"shop\\"'' | grep -qx SELECT ) && ( grep -q \\"INSERT command denied\\" /tmp/denied.txt ) && ( mariadb -N -e ''SELECT COUNT(*) FROM shop.items'' | grep -qx 5 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "reader 의 shop 권한이 SELECT 뿐이다", "cmd": ["sh", "-c", "mariadb -N -e ''SELECT GROUP_CONCAT(privilege_type) FROM information_schema.schema_privileges WHERE grantee LIKE \\"%reader%\\" AND table_schema=\\"shop\\"'' | grep -qx SELECT"]}, {"label": "거부 오류가 저장됐다", "cmd": ["sh", "-c", "grep -q \\"INSERT command denied\\" /tmp/denied.txt"]}, {"label": "데이터는 그대로 5행이다", "cmd": ["sh", "-c", "mariadb -N -e ''SELECT COUNT(*) FROM shop.items'' | grep -qx 5"]}]', '[{"title": "CREATE USER", "url": "https://mariadb.com/kb/en/create-user/"}, {"title": "GRANT", "url": "https://mariadb.com/kb/en/grant/"}, {"title": "Roles", "url": "https://mariadb.com/kb/en/roles_overview/"}]'),
  (507, 4, 'SHOW GRANTS 로 과한 권한 찾기', '보고서용으로 만든 계정 **`report`@`localhost`** 가 있습니다. 보고서는 조회만 하면 되는데 권한이 적절한지 점검하려 합니다. 이 계정의 **권한 목록을 `/tmp/report_grants.txt`** 에 저장하세요. (저장한 내용에 `ALL PRIVILEGES ON *.*` 가 있으면 서버 전체에 대한 모든 권한이라 과한 상태입니다.)', '`SHOW GRANTS FOR ''계정''@''호스트'';` 를 `mariadb -e` 로 실행하고 `>` 로 저장합니다. 계정 이름은 작은따옴표로 두 부분을 감쌉니다.', 'mariadb -e "SHOW GRANTS FOR ''report''@''localhost''" > /tmp/report_grants.txt
cat /tmp/report_grants.txt

# ON *.* 는 모든 DB·모든 테이블이다. ALL PRIVILEGES 가 *.* 에 있다면 사실상 관리자 권한이라 보고서 계정에 어울리지 않는다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP USER IF EXISTS \\"appuser\\"@\\"localhost\\"; DROP USER IF EXISTS \\"reader\\"@\\"localhost\\"; DROP USER IF EXISTS \\"report\\"@\\"localhost\\"; DROP USER IF EXISTS \\"olduser\\"@\\"localhost\\"; DROP USER IF EXISTS \\"alice\\"@\\"localhost\\"; DROP USER IF EXISTS \\"bob\\"@\\"localhost\\"; DROP USER IF EXISTS \\"backup\\"@\\"localhost\\"; DROP USER IF EXISTS \\"backup\\"@\\"%\\"; DROP ROLE IF EXISTS reader_role; DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; CREATE TABLE shop.items (id INT PRIMARY KEY, name VARCHAR(30), price INT); INSERT INTO shop.items VALUES (1,\\"apple\\",1000),(2,\\"pear\\",2000),(3,\\"grape\\",3000),(4,\\"peach\\",4000),(5,\\"plum\\",5000);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf; mariadb -e ''CREATE USER \\"report\\"@\\"localhost\\" IDENTIFIED BY \\"ReportPw1\\"; GRANT ALL PRIVILEGES ON *.* TO \\"report\\"@\\"localhost\\";''"]', '["sh", "-c", "( [ -s /tmp/report_grants.txt ] ) && ( grep -q \\"report\\" /tmp/report_grants.txt ) && ( grep -q \\"ALL PRIVILEGES ON \\\\*\\\\.\\\\*\\" /tmp/report_grants.txt )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "파일이 있다", "cmd": ["sh", "-c", "[ -s /tmp/report_grants.txt ]"]}, {"label": "report 의 권한 목록이다", "cmd": ["sh", "-c", "grep -q \\"report\\" /tmp/report_grants.txt"]}, {"label": "ALL PRIVILEGES 가 보인다", "cmd": ["sh", "-c", "grep -q \\"ALL PRIVILEGES ON \\\\*\\\\.\\\\*\\" /tmp/report_grants.txt"]}]', '[{"title": "CREATE USER", "url": "https://mariadb.com/kb/en/create-user/"}, {"title": "GRANT", "url": "https://mariadb.com/kb/en/grant/"}, {"title": "Roles", "url": "https://mariadb.com/kb/en/roles_overview/"}]'),
  (507, 5, 'REVOKE 로 권한 회수하고 필요한 것만 다시 주기', '앞에서 찾은 `report`@`localhost` 의 **서버 전체 권한을 회수**하고, 보고서에 필요한 **`shop.*` 의 `SELECT` 만** 다시 주세요. 끝나면 서버 전체(`*.*`)에는 사용 권한(`USAGE`, 접속만 가능)만 남아야 합니다.', '넓게 준 권한은 `REVOKE` 로 먼저 모두 회수한 뒤, 필요한 범위·종류만 `GRANT` 로 다시 줍니다. 결과는 `SHOW GRANTS FOR ...` 로 확인하세요.', 'mariadb -e "REVOKE ALL PRIVILEGES, GRANT OPTION FROM ''report''@''localhost''; GRANT SELECT ON shop.* TO ''report''@''localhost''"
mariadb -e "SHOW GRANTS FOR ''report''@''localhost''"

# 넓게 준 권한은 회수하고 필요한 범위·종류만 다시 준다. USAGE 는 ''권한 없음''(접속만 가능)을 뜻한다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP USER IF EXISTS \\"appuser\\"@\\"localhost\\"; DROP USER IF EXISTS \\"reader\\"@\\"localhost\\"; DROP USER IF EXISTS \\"report\\"@\\"localhost\\"; DROP USER IF EXISTS \\"olduser\\"@\\"localhost\\"; DROP USER IF EXISTS \\"alice\\"@\\"localhost\\"; DROP USER IF EXISTS \\"bob\\"@\\"localhost\\"; DROP USER IF EXISTS \\"backup\\"@\\"localhost\\"; DROP USER IF EXISTS \\"backup\\"@\\"%\\"; DROP ROLE IF EXISTS reader_role; DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; CREATE TABLE shop.items (id INT PRIMARY KEY, name VARCHAR(30), price INT); INSERT INTO shop.items VALUES (1,\\"apple\\",1000),(2,\\"pear\\",2000),(3,\\"grape\\",3000),(4,\\"peach\\",4000),(5,\\"plum\\",5000);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf; mariadb -e ''CREATE USER \\"report\\"@\\"localhost\\" IDENTIFIED BY \\"ReportPw1\\"; GRANT ALL PRIVILEGES ON *.* TO \\"report\\"@\\"localhost\\";''"]', '["sh", "-c", "( mariadb -N -e ''SELECT COUNT(*) FROM information_schema.user_privileges WHERE grantee LIKE \\"%report%\\" AND privilege_type<>\\"USAGE\\"'' | grep -qx 0 ) && ( mariadb -N -e ''SELECT GROUP_CONCAT(privilege_type) FROM information_schema.schema_privileges WHERE grantee LIKE \\"%report%\\" AND table_schema=\\"shop\\"'' | grep -qx SELECT ) && ( mariadb -N -e ''SELECT COUNT(*) FROM mysql.user WHERE user=\\"report\\"'' | grep -qx 1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "서버 전체 권한이 USAGE 뿐이다", "cmd": ["sh", "-c", "mariadb -N -e ''SELECT COUNT(*) FROM information_schema.user_privileges WHERE grantee LIKE \\"%report%\\" AND privilege_type<>\\"USAGE\\"'' | grep -qx 0"]}, {"label": "shop 에는 SELECT 만 있다", "cmd": ["sh", "-c", "mariadb -N -e ''SELECT GROUP_CONCAT(privilege_type) FROM information_schema.schema_privileges WHERE grantee LIKE \\"%report%\\" AND table_schema=\\"shop\\"'' | grep -qx SELECT"]}, {"label": "계정은 남아 있다", "cmd": ["sh", "-c", "mariadb -N -e ''SELECT COUNT(*) FROM mysql.user WHERE user=\\"report\\"'' | grep -qx 1"]}]', '[{"title": "CREATE USER", "url": "https://mariadb.com/kb/en/create-user/"}, {"title": "GRANT", "url": "https://mariadb.com/kb/en/grant/"}, {"title": "Roles", "url": "https://mariadb.com/kb/en/roles_overview/"}]'),
  (507, 6, '퇴사자 계정 삭제하기', '퇴사한 담당자의 계정 **`olduser`@`localhost`** 가 아직 남아 있습니다. 이 계정을 **삭제**하세요. 다른 계정(`appuser`)은 지우면 안 됩니다. 삭제 후에는 `olduser` 로 접속이 거부되어야 합니다.', '계정을 통째로 지우는 구문은 `DROP USER ''이름''@''호스트'';` 입니다. 지우기 전에 `SELECT user, host FROM mysql.user;` 로 대상이 맞는지 확인하세요.', 'mariadb -e ''SELECT user, host FROM mysql.user''
mariadb -e "DROP USER ''olduser''@''localhost''"
mariadb -e ''SELECT user, host FROM mysql.user''

# DROP USER 는 계정과 그 권한을 함께 지운다. 쓰지 않는 계정은 공격 경로가 되므로 남기지 않는다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP USER IF EXISTS \\"appuser\\"@\\"localhost\\"; DROP USER IF EXISTS \\"reader\\"@\\"localhost\\"; DROP USER IF EXISTS \\"report\\"@\\"localhost\\"; DROP USER IF EXISTS \\"olduser\\"@\\"localhost\\"; DROP USER IF EXISTS \\"alice\\"@\\"localhost\\"; DROP USER IF EXISTS \\"bob\\"@\\"localhost\\"; DROP USER IF EXISTS \\"backup\\"@\\"localhost\\"; DROP USER IF EXISTS \\"backup\\"@\\"%\\"; DROP ROLE IF EXISTS reader_role; DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; CREATE TABLE shop.items (id INT PRIMARY KEY, name VARCHAR(30), price INT); INSERT INTO shop.items VALUES (1,\\"apple\\",1000),(2,\\"pear\\",2000),(3,\\"grape\\",3000),(4,\\"peach\\",4000),(5,\\"plum\\",5000);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf; mariadb -e ''CREATE USER \\"olduser\\"@\\"localhost\\" IDENTIFIED BY \\"OldPass1\\"; GRANT SELECT ON shop.* TO \\"olduser\\"@\\"localhost\\"; CREATE USER \\"appuser\\"@\\"localhost\\" IDENTIFIED BY \\"AppPass1\\";''"]', '["sh", "-c", "( mariadb -N -e ''SELECT COUNT(*) FROM mysql.user WHERE user=\\"olduser\\"'' | grep -qx 0 ) && ( mariadb -N -e ''SELECT COUNT(*) FROM mysql.user WHERE user=\\"appuser\\"'' | grep -qx 1 ) && ( ! mariadb -uolduser -pOldPass1 -e \\"SELECT 1\\" >/dev/null 2>&1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "olduser 가 없다", "cmd": ["sh", "-c", "mariadb -N -e ''SELECT COUNT(*) FROM mysql.user WHERE user=\\"olduser\\"'' | grep -qx 0"]}, {"label": "appuser 는 남아 있다", "cmd": ["sh", "-c", "mariadb -N -e ''SELECT COUNT(*) FROM mysql.user WHERE user=\\"appuser\\"'' | grep -qx 1"]}, {"label": "olduser 로 접속이 안 된다", "cmd": ["sh", "-c", "! mariadb -uolduser -pOldPass1 -e \\"SELECT 1\\" >/dev/null 2>&1"]}]', '[{"title": "CREATE USER", "url": "https://mariadb.com/kb/en/create-user/"}, {"title": "GRANT", "url": "https://mariadb.com/kb/en/grant/"}, {"title": "Roles", "url": "https://mariadb.com/kb/en/roles_overview/"}]'),
  (507, 7, 'ROLE 로 묶어서 여러 명에게 주기', '분석팀 **`alice`**, **`bob`** (둘 다 `localhost`)이 같은 권한을 받아야 합니다. 계정마다 `GRANT` 하지 말고 **역할(ROLE) `reader_role`** 을 만들어 `shop.*` 의 `SELECT` 를 주고, 그 역할을 `alice` 와 `bob` 에게 부여하세요. 그리고 두 사람이 **접속하자마자** 조회할 수 있어야 합니다. (`alice` 비밀번호 `AlicePw1`, `bob` 비밀번호 `BobPw1`)', '`CREATE ROLE`, `GRANT SELECT ON shop.* TO 역할`, `GRANT 역할 TO 계정` 순서입니다. 역할을 받아도 접속할 때 자동으로 켜지지는 않습니다. 접속 직후 바로 쓰게 하는 "기본 역할" 지정 구문을 찾아보세요. 확인은 `mariadb -ualice -pAlicePw1 -e "SELECT COUNT(*) FROM shop.items"` 입니다.', 'mariadb -e "CREATE ROLE reader_role; GRANT SELECT ON shop.* TO reader_role; GRANT reader_role TO ''alice''@''localhost'', ''bob''@''localhost''; SET DEFAULT ROLE reader_role FOR ''alice''@''localhost''; SET DEFAULT ROLE reader_role FOR ''bob''@''localhost''"
mariadb -ualice -pAlicePw1 -e ''SELECT COUNT(*) FROM shop.items''

# 권한 묶음을 역할로 만들어 두면 사람이 바뀔 때 역할만 주고 뺀다. SET DEFAULT ROLE 이 없으면 역할이 꺼진 채로 접속해 1142 가 난다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP USER IF EXISTS \\"appuser\\"@\\"localhost\\"; DROP USER IF EXISTS \\"reader\\"@\\"localhost\\"; DROP USER IF EXISTS \\"report\\"@\\"localhost\\"; DROP USER IF EXISTS \\"olduser\\"@\\"localhost\\"; DROP USER IF EXISTS \\"alice\\"@\\"localhost\\"; DROP USER IF EXISTS \\"bob\\"@\\"localhost\\"; DROP USER IF EXISTS \\"backup\\"@\\"localhost\\"; DROP USER IF EXISTS \\"backup\\"@\\"%\\"; DROP ROLE IF EXISTS reader_role; DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; CREATE TABLE shop.items (id INT PRIMARY KEY, name VARCHAR(30), price INT); INSERT INTO shop.items VALUES (1,\\"apple\\",1000),(2,\\"pear\\",2000),(3,\\"grape\\",3000),(4,\\"peach\\",4000),(5,\\"plum\\",5000);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf; mariadb -e ''CREATE USER \\"alice\\"@\\"localhost\\" IDENTIFIED BY \\"AlicePw1\\"; CREATE USER \\"bob\\"@\\"localhost\\" IDENTIFIED BY \\"BobPw1\\";''"]', '["sh", "-c", "( mariadb -N -e ''SELECT COUNT(*) FROM mysql.user WHERE user=\\"reader_role\\" AND is_role=\\"Y\\"'' | grep -qx 1 ) && ( mariadb -ualice -pAlicePw1 -N -e \\"SELECT COUNT(*) FROM shop.items\\" | grep -qx 5 ) && ( mariadb -ubob -pBobPw1 -N -e \\"SELECT COUNT(*) FROM shop.items\\" | grep -qx 5 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "역할이 만들어져 있다", "cmd": ["sh", "-c", "mariadb -N -e ''SELECT COUNT(*) FROM mysql.user WHERE user=\\"reader_role\\" AND is_role=\\"Y\\"'' | grep -qx 1"]}, {"label": "alice 가 바로 조회된다", "cmd": ["sh", "-c", "mariadb -ualice -pAlicePw1 -N -e \\"SELECT COUNT(*) FROM shop.items\\" | grep -qx 5"]}, {"label": "bob 이 바로 조회된다", "cmd": ["sh", "-c", "mariadb -ubob -pBobPw1 -N -e \\"SELECT COUNT(*) FROM shop.items\\" | grep -qx 5"]}]', '[{"title": "CREATE USER", "url": "https://mariadb.com/kb/en/create-user/"}, {"title": "GRANT", "url": "https://mariadb.com/kb/en/grant/"}, {"title": "Roles", "url": "https://mariadb.com/kb/en/roles_overview/"}]'),
  (507, 8, '비밀번호 바꾸기', '`appuser`@`localhost` 의 비밀번호(`OldPass1`)가 유출되어 **`NewPass2`** 로 바꿔야 합니다. 비밀번호를 변경하세요. 바꾼 뒤에는 새 비밀번호로만 접속되고 옛 비밀번호로는 거부됩니다.', '`ALTER USER ''계정''@''호스트'' IDENTIFIED BY ''새비밀번호'';` 를 사용합니다. 권한은 그대로 유지됩니다.', 'mariadb -e "ALTER USER ''appuser''@''localhost'' IDENTIFIED BY ''NewPass2''"
mariadb -uappuser -pNewPass2 -e ''SELECT 1''

# 비밀번호만 바뀌고 GRANT 는 그대로다. 유출이 의심되면 바꾸고, 앱 설정 파일의 비밀번호도 함께 고쳐야 한다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP USER IF EXISTS \\"appuser\\"@\\"localhost\\"; DROP USER IF EXISTS \\"reader\\"@\\"localhost\\"; DROP USER IF EXISTS \\"report\\"@\\"localhost\\"; DROP USER IF EXISTS \\"olduser\\"@\\"localhost\\"; DROP USER IF EXISTS \\"alice\\"@\\"localhost\\"; DROP USER IF EXISTS \\"bob\\"@\\"localhost\\"; DROP USER IF EXISTS \\"backup\\"@\\"localhost\\"; DROP USER IF EXISTS \\"backup\\"@\\"%\\"; DROP ROLE IF EXISTS reader_role; DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; CREATE TABLE shop.items (id INT PRIMARY KEY, name VARCHAR(30), price INT); INSERT INTO shop.items VALUES (1,\\"apple\\",1000),(2,\\"pear\\",2000),(3,\\"grape\\",3000),(4,\\"peach\\",4000),(5,\\"plum\\",5000);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf; mariadb -e ''CREATE USER \\"appuser\\"@\\"localhost\\" IDENTIFIED BY \\"OldPass1\\"; GRANT SELECT ON shop.* TO \\"appuser\\"@\\"localhost\\";''"]', '["sh", "-c", "( mariadb -uappuser -pNewPass2 -N -e \\"SELECT 1\\" | grep -qx 1 ) && ( ! mariadb -uappuser -pOldPass1 -e \\"SELECT 1\\" >/dev/null 2>&1 ) && ( mariadb -uappuser -pNewPass2 -N -e \\"SELECT COUNT(*) FROM shop.items\\" | grep -qx 5 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "새 비밀번호로 접속된다", "cmd": ["sh", "-c", "mariadb -uappuser -pNewPass2 -N -e \\"SELECT 1\\" | grep -qx 1"]}, {"label": "옛 비밀번호는 거부된다", "cmd": ["sh", "-c", "! mariadb -uappuser -pOldPass1 -e \\"SELECT 1\\" >/dev/null 2>&1"]}, {"label": "권한은 그대로다", "cmd": ["sh", "-c", "mariadb -uappuser -pNewPass2 -N -e \\"SELECT COUNT(*) FROM shop.items\\" | grep -qx 5"]}]', '[{"title": "CREATE USER", "url": "https://mariadb.com/kb/en/create-user/"}, {"title": "GRANT", "url": "https://mariadb.com/kb/en/grant/"}, {"title": "Roles", "url": "https://mariadb.com/kb/en/roles_overview/"}]'),
  (507, 9, '원격 접속 호스트 제한하기', '백업 계정 **`backup`@`%`** 는 어느 곳에서나 접속할 수 있게 만들어져 있습니다. 백업은 이 서버 안에서만 실행되므로 **접속 허용 위치를 `localhost` 로 바꿔** 원격 접속을 막으세요. 계정을 지우고 다시 만들지 말고 **이름을 바꾸는 구문**으로 호스트 부분만 변경해 권한과 비밀번호를 유지합니다.', '`RENAME USER ''이름''@''옛호스트'' TO ''이름''@''새호스트'';` 입니다. 끝나면 `SELECT user, host FROM mysql.user;` 로 호스트가 바뀌었는지 보세요.', 'mariadb -e "RENAME USER ''backup''@''%'' TO ''backup''@''localhost''"
mariadb -e ''SELECT user, host FROM mysql.user WHERE user="backup"''

# ''%'' 계정은 네트워크 어디서든 비밀번호만 맞으면 들어온다. 접속 위치를 좁히면 계정이 유출돼도 위험이 줄어든다. 서버 자체가 외부에 열려 있는지는 bind-address 설정으로 따로 막는다', '["sh", "-c", "nohup mysqld_safe >/dev/null 2>&1 & for i in $(seq 1 60); do mariadb -e ''select 1'' >/dev/null 2>&1 && break; sleep 0.5; done; mariadb -e ''DROP USER IF EXISTS \\"appuser\\"@\\"localhost\\"; DROP USER IF EXISTS \\"reader\\"@\\"localhost\\"; DROP USER IF EXISTS \\"report\\"@\\"localhost\\"; DROP USER IF EXISTS \\"olduser\\"@\\"localhost\\"; DROP USER IF EXISTS \\"alice\\"@\\"localhost\\"; DROP USER IF EXISTS \\"bob\\"@\\"localhost\\"; DROP USER IF EXISTS \\"backup\\"@\\"localhost\\"; DROP USER IF EXISTS \\"backup\\"@\\"%\\"; DROP ROLE IF EXISTS reader_role; DROP DATABASE IF EXISTS shop; CREATE DATABASE shop; CREATE TABLE shop.items (id INT PRIMARY KEY, name VARCHAR(30), price INT); INSERT INTO shop.items VALUES (1,\\"apple\\",1000),(2,\\"pear\\",2000),(3,\\"grape\\",3000),(4,\\"peach\\",4000),(5,\\"plum\\",5000);''; rm -f /tmp/*.txt /tmp/*.sh /tmp/*.sql /tmp/*.cnf; mariadb -e ''CREATE USER \\"backup\\"@\\"%\\" IDENTIFIED BY \\"BackPass1\\"; GRANT SELECT, LOCK TABLES ON shop.* TO \\"backup\\"@\\"%\\";''"]', '["sh", "-c", "( mariadb -N -e ''SELECT GROUP_CONCAT(host) FROM mysql.user WHERE user=\\"backup\\"'' | grep -qx localhost ) && ( mariadb -N -e ''SELECT GROUP_CONCAT(privilege_type ORDER BY privilege_type) FROM information_schema.schema_privileges WHERE grantee LIKE \\"%backup%\\" AND table_schema=\\"shop\\"'' | grep -qx \\"LOCK TABLES,SELECT\\" ) && ( mariadb -ubackup -pBackPass1 -N -e \\"SELECT 1\\" | grep -qx 1 )"]', 'terminal', NULL, NULL, NULL, NULL, NULL, '[{"label": "backup 계정은 localhost 하나뿐이다", "cmd": ["sh", "-c", "mariadb -N -e ''SELECT GROUP_CONCAT(host) FROM mysql.user WHERE user=\\"backup\\"'' | grep -qx localhost"]}, {"label": "권한이 유지됐다", "cmd": ["sh", "-c", "mariadb -N -e ''SELECT GROUP_CONCAT(privilege_type ORDER BY privilege_type) FROM information_schema.schema_privileges WHERE grantee LIKE \\"%backup%\\" AND table_schema=\\"shop\\"'' | grep -qx \\"LOCK TABLES,SELECT\\""]}, {"label": "비밀번호가 유지됐다", "cmd": ["sh", "-c", "mariadb -ubackup -pBackPass1 -N -e \\"SELECT 1\\" | grep -qx 1"]}]', '[{"title": "CREATE USER", "url": "https://mariadb.com/kb/en/create-user/"}, {"title": "GRANT", "url": "https://mariadb.com/kb/en/grant/"}, {"title": "Roles", "url": "https://mariadb.com/kb/en/roles_overview/"}]'),
  (507, 10, '가장 안전한 앱 계정 설계', '앱 서버(`192.0.2.10`) 한 곳에서만 `shop` 데이터베이스의 데이터를 조회·추가·수정·삭제하는 앱 계정을 만듭니다. 가장 안전한 정의는 무엇인가요?', '두 가지를 모두 좁혀 보세요. 접속할 수 있는 위치(계정의 호스트 부분)와 줄 권한의 범위입니다.', NULL, NULL, '[]', 'choice', '["`''app''@''%''` 에 `*.*` 의 `ALL PRIVILEGES` 를 준다", "`''app''@''localhost''` 에 `*.*` 의 `ALL PRIVILEGES` 를 준다", "`''root''@''%''` 를 앱과 같이 쓴다", "`''app''@''192.0.2.10''` 에 `shop.*` 의 `SELECT, INSERT, UPDATE, DELETE` 만 준다"]', 3, '접속 위치를 앱 서버 한 곳으로 좁히고, 권한도 필요한 DB 와 필요한 동작으로만 제한한 것이 최소 권한입니다. `%` 는 어디서든 접속을 허용하고, `*.* ALL PRIVILEGES` 는 서버 전체 관리자 권한이며, root 를 공유하면 앱이 침해될 때 서버 전체가 넘어갑니다. (localhost 로만 적으면 다른 서버의 앱은 접속하지 못합니다.)', NULL, NULL, NULL, NULL),
  (507, 11, '접속 직후 켜질 기본 역할 지정', '`alice` 에게 역할을 줬는데 접속하면 권한이 없다고 나옵니다. 접속하자마자 `reader_role` 이 **자동으로 켜지게** 하는 구문의 빈칸을 채우세요.', '역할은 부여만 해서는 켜지지 않습니다. "기본으로 켤 역할"을 계정에 대해 지정합니다.', NULL, NULL, '[]', 'fill', '["FOR", "TO", "ON", "FROM"]', NULL, '`SET DEFAULT ROLE 역할 FOR 계정` 이 접속 때 자동으로 켤 역할을 정합니다. TO, ON, FROM 은 이 구문에 쓰이지 않습니다. 부여(`GRANT 역할 TO 계정`)와 활성화는 별개입니다.', '[0]', 'SET DEFAULT ROLE reader_role {0} ''alice''@''localhost'';', NULL, NULL),
  (507, 12, '퇴사자 계정 정리 순서', '퇴사자 계정을 안전하게 정리하는 순서로 놓으세요.', '지울 대상이 맞는지는 삭제 전에 눈으로 확인합니다. 작업이 끝난 뒤에는 정말 막혔는지 검증하는 단계가 따로 있습니다.', NULL, NULL, '[]', 'order', '["DROP USER 로 계정을 삭제한다", "그 계정으로 접속해 거부되는지 확인한다", "SHOW GRANTS 로 계정과 권한을 확인한다", "REVOKE 로 남은 권한을 회수한다"]', NULL, '지울 계정이 맞는지 SHOW GRANTS 로 먼저 확인하고, 권한부터 REVOKE 로 회수해 접근을 단계적으로 끊은 뒤 DROP USER 로 삭제합니다(DROP USER 만으로도 권한은 함께 지워지지만, 이 문제는 단계별 정리 절차를 묻습니다). 마지막에 그 계정으로 접속해 거부되는지 확인하면 정리가 끝난 것입니다.', '[2, 3, 0, 1]', NULL, NULL, NULL);
